// ===== 工具函数 =====
export function getPublicReadyPeople(): BFStoryMirrorPerson[] {
  return BF_STORY_MIRROR_PEOPLE.filter(p => p.review_status === 'public_ready');
}

export function searchPeopleByTraitConnection(
  dim: string,
  limit: number = 10
): BFStoryMirrorPerson[] {
  return BF_STORY_MIRROR_PEOPLE
    .filter(p => 
      p.review_status === 'public_ready' && 
      p.possible_trait_connections.some(c => c.startsWith(dim))
    )
    .sort((a, b) => b.editorial_quality - a.editorial_quality)
    .slice(0, limit);
}

export function getPeopleStats() {
  const total = BF_STORY_MIRROR_PEOPLE.length;
  const publicReady = BF_STORY_MIRROR_PEOPLE.filter(p => p.review_status === 'public_ready').length;
  const cultures = new Set(BF_STORY_MIRROR_PEOPLE.map(p => p.culture_region));
  const fields = new Set(BF_STORY_MIRROR_PEOPLE.map(p => p.field));
  return { total, publicReady, cultures: cultures.size, fields: fields.size };
}

export default BF_STORY_MIRROR_PEOPLE;
